-- Cost breakdown per price book row (Material / Hardware / Factory / Drafting / Studio / Install).
-- The book "rate" stays the all-in cost per unit; these six columns say where that cost goes.
-- Safe to run more than once. Does NOT delete or replace any rows.
begin;

alter table default_price_book_items
  add column if not exists cost_material numeric(10,2),
  add column if not exists cost_hardware numeric(10,2),
  add column if not exists cost_factory numeric(10,2),
  add column if not exists cost_drafting numeric(10,2),
  add column if not exists cost_studio numeric(10,2),
  add column if not exists cost_install numeric(10,2);
alter table price_book_items
  add column if not exists cost_material numeric(10,2),
  add column if not exists cost_hardware numeric(10,2),
  add column if not exists cost_factory numeric(10,2),
  add column if not exists cost_drafting numeric(10,2),
  add column if not exists cost_studio numeric(10,2),
  add column if not exists cost_install numeric(10,2);

-- New signups copy the breakdown along with the rest of the default book.
create or replace function handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  new_org_id uuid;
begin
    returning id into new_org_id;

    values (new.id, new_org_id, coalesce(new.raw_user_meta_data->>'full_name', ''), 'owner');

    cost_material, cost_hardware, cost_factory, cost_drafting, cost_studio, cost_install)
    select new_org_id, calc, section, category, name, rate, unit, sort_order,
    cost_material, cost_hardware, cost_factory, cost_drafting, cost_studio, cost_install
    from default_price_book_items;

  return new;
end;
$$;

-- Load Vicello's numbers from "Material cost / Labour cost (book pricing)".
-- Matches on category + name + total rate, so a row only gets a breakdown when the
-- sheet and the book agree exactly. Rows that don't match are left blank and show
-- as "Not broken down" in the quote profit panel.
create temp table _cost_src (category text, name text, rate numeric, m numeric, h numeric, f numeric, d numeric, s numeric, i numeric) on commit drop;

update default_price_book_items p set
  cost_material = v.m, cost_hardware = v.h, cost_factory = v.f,
  cost_drafting = v.d, cost_studio = v.s, cost_install = v.i
from _cost_src v where p.category = v.category and p.name = v.name and p.rate = v.rate;

update price_book_items p set
  cost_material = v.m, cost_hardware = v.h, cost_factory = v.f,
  cost_drafting = v.d, cost_studio = v.s, cost_install = v.i
from _cost_src v where p.category = v.category and p.name = v.name and p.rate = v.rate;

commit;
